import shutil
import subprocess
from pathlib import Path

STAGING_DIR = Path("/srv/config/staging")
LIVE_DIR = Path("/srv/config/live")


def _run_reload(config_path: Path) -> subprocess.CompletedProcess:
    return subprocess.run(["/usr/local/bin/config-reload", "--file", str(config_path)], capture_output=True, text=True, timeout=120)


@function_tool
def promote_staged_config_and_reload(bundle_filename: str) -> dict:
    source = STAGING_DIR / Path(bundle_filename).name
    if not source.is_file():
        return {"promoted": False, "error": f"Staged bundle '{bundle_filename}' not found."}
    target = LIVE_DIR / source.name
    shutil.move(str(source), str(target))
    result = _run_reload(target)
    return {"promoted": True, "live_path": str(target), "reload_exit_code": result.returncode, "reload_output": (result.stdout or result.stderr)[-2000:]}
